// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom'; // 💡 useNavigate 추가
import Main from './Main';
import Login from './Login/Login';
import Signup from './Login/Signup';
import TempleList from './Temples/TempleList'; // 사찰 목록 컴포넌트
import TempleDetail from './Temples/TempleDetail'; // 사찰 상세 컴포넌트
import TempleRegister from './Temples/TempleRegister'; // 사찰 등록 컴포넌트
import TempleEdit from './Temples/TempleUpdate'; // 사찰 수정 컴포넌트
// import ReviewsApp from './Reviews/ReviewsApp'; // 💡💡💡 ReviewsApp 임포트 제거 💡💡💡
import ReviewList from './Reviews/ReviewList'; // 💡💡💡 ReviewList 임포트 추가 💡💡💡
import ReviewDetail from './Reviews/ReviewDetail'; // 리뷰 상세 컴포넌트
import ReviewCreate from './Reviews/ReviewRegister'; // 💡💡💡 ReviewCreate 대신 ReviewRegister 임포트 및 이름 변경 💡💡💡
import ReviewUpdate from './Reviews/ReviewUpdate'; // 💡💡💡 ReviewUpdate 컴포넌트 임포트 추가 💡💡💡

import { AuthProvider, useAuth } from './Context/AuthContext'; // AuthProvider와 useAuth 임포트
import axios from 'axios';
import ReviewRegister from './Reviews/ReviewRegister';

// Axios 인터셉터 설정: 모든 요청에 토큰 추가
axios.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('accessToken');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Axios 인터셉터 설정: 응답 오류 처리
axios.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;
    // 401 Unauthorized 에러 발생 시 (토큰 만료 등)
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true; // 재시도 플래그 설정
      // 여기서 refreshToken을 사용하여 새 accessToken을 발급받거나,
      // 사용자에게 재로그인 안내 후 로그인 페이지로 리다이렉트할 수 있습니다.
      // 예시: 로그인 페이지로 강제 리다이렉트
      localStorage.removeItem('accessToken');
      window.location.href = '/login'; // 페이지 새로고침과 함께 로그인 페이지로 이동
      return Promise.reject(error);
    }
    return Promise.reject(error);
  }
);


// Header 컴포넌트를 App 컴포넌트 바깥에 정의하거나,
// App 컴포넌트 내부에 정의하되 useAuth 훅을 사용할 수 있도록 AuthProvider 내부에 렌더링되도록 합니다.
// 여기서는 App 컴포넌트 내부에 배치하고 AuthProvider로 감싸는 방식을 사용합니다.
const Header = () => {
  const { isLoggedIn, logout, hasAdminPermission } = useAuth(); // useAuth 훅 사용
  const navigate = useNavigate(); // 💡 Header 컴포넌트 내에서 useNavigate 임포트

  const handleLogout = () => {
    logout();
    navigate('/'); // 로그아웃 후 메인 페이지로 이동
  };

  return (
    <header className="bg-gradient-to-r from-green-700 to-blue-700 text-white p-4 shadow-md">
      <nav className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-3xl font-extrabold flex items-center space-x-2">
          <span role="img" aria-label="buddha" className="text-4xl">🙏</span>
          <span>붓다로드</span>
        </Link>
        <ul className="flex space-x-6 text-lg font-medium">
          <li>
            <Link to="/temples" className="hover:text-gray-200 transition-colors duration-300">사찰</Link>
          </li>
          <li>
            <Link to="/reviews" className="hover:text-gray-200 transition-colors duration-300">리뷰</Link>
          </li>
          {hasAdminPermission() && ( // 💡 관리자 권한이 있는 경우만 보이도록
            <li>
              <Link to="/temples/register" className="hover:text-gray-200 transition-colors duration-300">사찰등록</Link>
            </li>
          )}
          {isLoggedIn ? (
            <li>
              <button onClick={handleLogout} className="hover:text-gray-200 transition-colors duration-300">로그아웃</button>
            </li>
          ) : (
            <>
              <li>
                <Link to="/login" className="hover:text-gray-200 transition-colors duration-300">로그인</Link>
              </li>
              <li>
                <Link to="/signup" className="hover:text-gray-200 transition-colors duration-300">회원가입</Link>
              </li>
            </>
          )}
        </ul>
      </nav>
    </header>
  );
};

function App() {
  return (
    <AuthProvider> {/* AuthProvider로 전체 앱 감싸기 */}
      <Router>
        <Header /> {/* Header 컴포넌트를 Router 안에 배치 */}
        <main className="p-4">
          <Routes>
            <Route path="/" element={<Main />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/temples" element={<TempleList />} />
            <Route path="/temples/:templeId" element={<TempleDetail />} />
            <Route path="/temples/register" element={<TempleRegister />} />
            <Route path="/temples/edit/:templeId" element={<TempleEdit />} />

            {/* 💡💡💡 리뷰 관련 라우트 순서 조정 및 ReviewCreate, ReviewUpdate 라우트 활성화 💡💡💡 */}
            {/* 가장 구체적인 경로들을 먼저 정의 */}
            <Route path="/reviews/register" element={<ReviewRegister/>} /> {/* ⭐ 여기를 변경! ⭐ */}
            {/* 리뷰 수정 경로 추가: reviewId 파라미터 받음 */}
            <Route path="/reviews/edit/:reviewId" element={<ReviewUpdate />} /> {/* 💡 ReviewUpdate 추가 */}
            {/* 그 다음으로 파라미터를 받는 일반적인 경로를 정의 (리뷰 상세) */}
            <Route path="/reviews/:reviewId" element={<ReviewDetail />} />
            {/* 마지막으로 가장 일반적인 경로 (리뷰 목록)를 정의 */}
            <Route path="/reviews" element={<ReviewList />} /> 
          </Routes>
        </main>
      </Router>
    </AuthProvider>
  );
}

export default App;
